@@ -455,6 +456,8 @@ bool ptdump_walk_pgd_level_core(struct seq_file *m,
                .seq            = m
        };

+       st.first_level = ptdump_pt_level_first(mm);
+
        ptdump_walk_pgd(&st.ptdump, mm, pgd);

        if (!checkwx)
