-				  unsigned int *level, bool *nx, bool *rw)
+				  unsigned int *level,
+				  bool *ret_nx, bool *ret_rw)
 {
+	unsigned long rw = _PAGE_RW;
+	unsigned long nx = 0;
+	pte_t *pte = NULL;
 	p4d_t *p4d;
 	pud_t *pud;
 	pmd_t *pmd;
 
 	*level = PG_LEVEL_256T;
-	*nx = false;
-	*rw = true;
-
 	if (pgd_none(*pgd))
-		return NULL;
+		goto out;
 
 	*level = PG_LEVEL_512G;
-	*nx |= pgd_flags(*pgd) & _PAGE_NX;
-	*rw &= pgd_flags(*pgd) & _PAGE_RW;
+	nx |= pgd_flags(*pgd) & _PAGE_NX;
+	rw &= pgd_flags(*pgd) & _PAGE_RW;
 
 	p4d = p4d_offset(pgd, address);
 	if (p4d_none(*p4d))
-		return NULL;
