+static void wprobe_trigger_data_rcu_free(struct rcu_head *rcu)
+{
+	struct wprobe_trigger_data *wprobe_data =
+		container_of(rcu, struct wprobe_trigger_data, rcu);
+	free_wprobe_trigger_data(wprobe_data);
+}
